import React, { useState, useEffect, useRef } from 'react';
import { toast } from 'react-toastify';
import { FiPlus, FiEdit2, FiTrash2 } from 'react-icons/fi';
import api, { getApiErrorMessage } from '../../services/api';
import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

const initialCourseForm = {
  title: '',
  slug: '',
  description: '',
  short_description: '',
  duration: '',
  level: '',
  price: '',
  is_active: true,
  is_featured: false,
  order: 0,
  category_id: '',
};

const initialCategoryForm = {
  name: '',
  slug: '',
  description: '',
  is_active: true,
  order: 0,
};

const AdminCourses = () => {
  const [courses, setCourses] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);

  // Course state
  const [courseModalOpen, setCourseModalOpen] = useState(false);
  const [editingCourse, setEditingCourse] = useState(null);
  const [courseFormData, setCourseFormData] = useState(initialCourseForm);
  const [courseImageFile, setCourseImageFile] = useState(null);
  const courseFileRef = useRef(null);

  // Category state
  const [categoryModalOpen, setCategoryModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState(null);
  const [categoryFormData, setCategoryFormData] = useState(initialCategoryForm);
  const [categoryImageFile, setCategoryImageFile] = useState(null);
  const categoryFileRef = useRef(null);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [coursesResponse, categoriesResponse] = await Promise.all([
        api.get('/api/courses/?is_active=true'),
        api.get('/api/courses/categories'),
      ]);
      setCourses(coursesResponse.data);
      setCategories(categoriesResponse.data);
    } catch (error) {
      toast.error(getApiErrorMessage(error, 'Failed to load courses data'));
    } finally {
      setLoading(false);
    }
  };

  const resetCourseForm = () => {
    setEditingCourse(null);
    setCourseFormData(initialCourseForm);
    setCourseImageFile(null);
    if (courseFileRef.current) courseFileRef.current.value = '';
  };

  const resetCategoryForm = () => {
    setEditingCategory(null);
    setCategoryFormData(initialCategoryForm);
    setCategoryImageFile(null);
    if (categoryFileRef.current) categoryFileRef.current.value = '';
  };

  const handleCourseSubmit = async (e) => {
    e.preventDefault();
    try {
      const fd = new FormData();
      fd.append('title', courseFormData.title);
      fd.append('slug', courseFormData.slug);
      fd.append('description', courseFormData.description || '');
      fd.append('short_description', courseFormData.short_description || '');
      fd.append('duration', courseFormData.duration || '');
      fd.append('level', courseFormData.level || '');
      fd.append('price', courseFormData.price || '');
      fd.append('is_active', String(courseFormData.is_active));
      fd.append('is_featured', String(courseFormData.is_featured));
      fd.append('order', String(courseFormData.order));
      fd.append('category_id', String(courseFormData.category_id));
      if (courseImageFile) fd.append('image_file', courseImageFile);

      if (editingCourse) {
        await api.put(`/api/courses/${editingCourse.id}`, fd, {
          headers: { 'Content-Type': 'multipart/form-data' },
        });
        toast.success('Course updated successfully');
      } else {
        await api.post('/api/courses/', fd, {
          headers: { 'Content-Type': 'multipart/form-data' },
        });
        toast.success('Course created successfully');
      }
      setCourseModalOpen(false);
      resetCourseForm();
      fetchData();
    } catch (error) {
      const msg = error.response?.data?.detail || 'Failed to save course';
      toast.error(msg);
      console.error(error);
    }
  };

  const handleDeleteCourse = async (id) => {
    if (!window.confirm('Are you sure you want to delete this course?')) return;
    try {
      await api.delete(`/api/courses/${id}`);
      toast.success('Course deleted successfully');
      fetchData();
    } catch (error) {
      toast.error(getApiErrorMessage(error, 'Failed to delete course'));
    }
  };

  const handleEditCourse = (course) => {
    setEditingCourse(course);
    setCourseFormData({
      title: course.title || '',
      slug: course.slug || '',
      description: course.description || '',
      short_description: course.short_description || '',
      duration: course.duration || '',
      level: course.level || '',
      price: course.price || '',
      is_active: !!course.is_active,
      is_featured: !!course.is_featured,
      order: course.order || 0,
      category_id: course.category_id || '',
    });
    setCourseImageFile(null);
    setCourseModalOpen(true);
  };

  const handleCategorySubmit = async (e) => {
    e.preventDefault();
    try {
      const fd = new FormData();
      fd.append('name', categoryFormData.name);
      fd.append('slug', categoryFormData.slug);
      fd.append('description', categoryFormData.description || '');
      fd.append('is_active', String(categoryFormData.is_active));
      fd.append('order', String(categoryFormData.order));
      if (categoryImageFile) fd.append('image_file', categoryImageFile);

      if (editingCategory) {
        await api.put(`/api/courses/categories/${editingCategory.id}`, fd, {
          headers: { 'Content-Type': 'multipart/form-data' },
        });
        toast.success('Category updated successfully');
      } else {
        await api.post('/api/courses/categories', fd, {
          headers: { 'Content-Type': 'multipart/form-data' },
        });
        toast.success('Category created successfully');
      }
      setCategoryModalOpen(false);
      resetCategoryForm();
      fetchData();
    } catch (error) {
      const msg = error.response?.data?.detail || 'Failed to save category';
      toast.error(msg);
      console.error(error);
    }
  };

  const handleDeleteCategory = async (id) => {
    if (!window.confirm('Are you sure you want to delete this category?')) return;
    try {
      await api.delete(`/api/courses/categories/${id}`);
      toast.success('Category deleted successfully');
      fetchData();
    } catch (error) {
      toast.error(getApiErrorMessage(error, 'Failed to delete category'));
    }
  };

  const handleEditCategory = (category) => {
    setEditingCategory(category);
    setCategoryFormData({
      name: category.name || '',
      slug: category.slug || '',
      description: category.description || '',
      is_active: !!category.is_active,
      order: category.order || 0,
    });
    setCategoryImageFile(null);
    setCategoryModalOpen(true);
  };

  const courseColumns = [
    {
      key: 'image_url',
      label: 'Image',
      render: (val) => (
        <img src={val || 'https://via.placeholder.com/60x40?text=No+Img'} alt="course" className="w-16 h-10 object-cover rounded" />
      ),
    },
    { key: 'title', label: 'Title' },
    {
      key: 'category_id',
      label: 'Category',
      render: (val) => categories.find((c) => c.id === val)?.name || '-',
    },
    { key: 'duration', label: 'Duration' },
    { key: 'price', label: 'Price' },
    { key: 'level', label: 'Level' },
    {
      key: 'is_active',
      label: 'Status',
      render: (val) => (
        <span className={`px-2 py-1 rounded-full text-xs ${val ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
          {val ? 'Active' : 'Inactive'}
        </span>
      ),
    },
    {
      key: 'actions',
      label: 'Actions',
      render: (_, row) => (
        <div className="flex space-x-2">
          <button onClick={() => handleEditCourse(row)} className="text-blue-600 hover:text-blue-800">
            <FiEdit2 />
          </button>
          <button onClick={() => handleDeleteCourse(row.id)} className="text-red-600 hover:text-red-800">
            <FiTrash2 />
          </button>
        </div>
      ),
    },
  ];

  const categoryColumns = [
    {
      key: 'image_url',
      label: 'Image',
      render: (val) => (
        <img src={val || 'https://via.placeholder.com/60x40?text=No+Img'} alt="category" className="w-16 h-10 object-cover rounded" />
      ),
    },
    { key: 'name', label: 'Name' },
    { key: 'slug', label: 'Slug' },
    {
      key: 'is_active',
      label: 'Status',
      render: (val) => (
        <span className={`px-2 py-1 rounded-full text-xs ${val ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
          {val ? 'Active' : 'Inactive'}
        </span>
      ),
    },
    {
      key: 'actions',
      label: 'Actions',
      render: (_, row) => (
        <div className="flex space-x-2">
          <button onClick={() => handleEditCategory(row)} className="text-blue-600 hover:text-blue-800">
            <FiEdit2 />
          </button>
          <button onClick={() => handleDeleteCategory(row.id)} className="text-red-600 hover:text-red-800">
            <FiTrash2 />
          </button>
        </div>
      ),
    },
  ];

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-blue-900">Courses Management</h1>
        <div className="flex space-x-2">
          <button
            onClick={() => {
              resetCategoryForm();
              setCategoryModalOpen(true);
            }}
            className="admin-btn-secondary flex items-center space-x-2"
          >
            <FiPlus />
            <span>Add Category</span>
          </button>
          <button
            onClick={() => {
              resetCourseForm();
              setCourseModalOpen(true);
            }}
            className="admin-btn-primary flex items-center space-x-2"
          >
            <FiPlus />
            <span>Add Course</span>
          </button>
        </div>
      </div>

      <div className="space-y-6">
        <AdminCard>
          <div className="p-4 border-b border-gray-100">
            <h2 className="text-xl font-bold text-blue-900">Course Categories</h2>
          </div>
          <AdminTable columns={categoryColumns} data={categories} loading={loading} />
        </AdminCard>

        <AdminCard>
          <div className="p-4 border-b border-gray-100">
            <h2 className="text-xl font-bold text-blue-900">Courses</h2>
          </div>
          <AdminTable columns={courseColumns} data={courses} loading={loading} />
        </AdminCard>
      </div>

      {/* Course Modal */}
      <AdminModal
        isOpen={courseModalOpen}
        onClose={() => { setCourseModalOpen(false); resetCourseForm(); }}
        title={editingCourse ? 'Edit Course' : 'Create Course'}
      >
        <form onSubmit={handleCourseSubmit}>
          <div className="grid grid-cols-2 gap-4">
            <div className="col-span-2">
              <label className="admin-label">Title *</label>
              <input
                type="text"
                value={courseFormData.title}
                onChange={(e) =>
                  setCourseFormData({
                    ...courseFormData,
                    title: e.target.value,
                    slug: e.target.value.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, ''),
                  })
                }
                className="admin-input"
                required
              />
            </div>
            <div>
              <label className="admin-label">Slug *</label>
              <input type="text" value={courseFormData.slug} onChange={(e) => setCourseFormData({ ...courseFormData, slug: e.target.value })} className="admin-input" required />
            </div>
            <div>
              <label className="admin-label">Category *</label>
              <select value={courseFormData.category_id} onChange={(e) => setCourseFormData({ ...courseFormData, category_id: e.target.value })} className="admin-input" required>
                <option value="">Select Category</option>
                {categories.map((cat) => (
                  <option key={cat.id} value={cat.id}>{cat.name}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="admin-label">Duration</label>
              <input type="text" value={courseFormData.duration} onChange={(e) => setCourseFormData({ ...courseFormData, duration: e.target.value })} className="admin-input" />
            </div>
            <div>
              <label className="admin-label">Level</label>
              <input type="text" value={courseFormData.level} onChange={(e) => setCourseFormData({ ...courseFormData, level: e.target.value })} className="admin-input" />
            </div>
            <div>
              <label className="admin-label">Price</label>
              <input type="text" value={courseFormData.price} onChange={(e) => setCourseFormData({ ...courseFormData, price: e.target.value })} className="admin-input" />
            </div>
            <div className="col-span-2">
              <label className="admin-label">Image</label>
              <div className="border-2 border-dashed border-gray-300 rounded-lg p-4 text-center hover:border-blue-900 transition cursor-pointer bg-gray-50/50" onClick={() => courseFileRef.current?.click()}>
                <input ref={courseFileRef} type="file" accept="image/jpeg,image/png,image/webp" onChange={(e) => setCourseImageFile(e.target.files?.[0] || null)} style={{ display: 'none' }} />
                {courseImageFile ? (
                  <p className="text-sm text-blue-900 font-medium">{courseImageFile.name}</p>
                ) : (
                  <>
                    <div className="text-3xl mb-2">📷</div>
                    <p className="text-sm text-gray-500 font-medium">Click to upload course image</p>
                    <p className="text-xs text-gray-400 mt-1">JPG, PNG, WEBP allowed</p>
                    {editingCourse && editingCourse.image_url && (
                      <p className="text-xs text-blue-500 mt-2">Current image will be kept if no new file selected</p>
                    )}
                  </>
                )}
              </div>
            </div>
            <div className="col-span-2">
              <label className="admin-label">Short Description</label>
              <textarea value={courseFormData.short_description} onChange={(e) => setCourseFormData({ ...courseFormData, short_description: e.target.value })} className="admin-input" rows="2" />
            </div>
            <div className="col-span-2">
              <label className="admin-label">Description</label>
              <textarea value={courseFormData.description} onChange={(e) => setCourseFormData({ ...courseFormData, description: e.target.value })} className="admin-input" rows="4" />
            </div>
            <div>
              <label className="admin-label">Order</label>
              <input type="number" value={courseFormData.order} onChange={(e) => setCourseFormData({ ...courseFormData, order: e.target.value })} className="admin-input" />
            </div>
            <div className="flex items-center space-x-6 mt-6">
              <label className="flex items-center space-x-2">
                <input type="checkbox" checked={courseFormData.is_active} onChange={(e) => setCourseFormData({ ...courseFormData, is_active: e.target.checked })} />
                <span>Active</span>
              </label>
              <label className="flex items-center space-x-2">
                <input type="checkbox" checked={courseFormData.is_featured} onChange={(e) => setCourseFormData({ ...courseFormData, is_featured: e.target.checked })} />
                <span>Featured</span>
              </label>
            </div>
          </div>
          <div className="mt-6 flex justify-end space-x-3">
            <button type="button" onClick={() => { setCourseModalOpen(false); resetCourseForm(); }} className="admin-btn-secondary">Cancel</button>
            <button type="submit" className="admin-btn-primary">{editingCourse ? 'Update' : 'Create'}</button>
          </div>
        </form>
      </AdminModal>

      {/* Category Modal */}
      <AdminModal
        isOpen={categoryModalOpen}
        onClose={() => { setCategoryModalOpen(false); resetCategoryForm(); }}
        title={editingCategory ? 'Edit Category' : 'Create Category'}
      >
        <form onSubmit={handleCategorySubmit}>
          <div className="space-y-4">
            <div>
              <label className="admin-label">Name *</label>
              <input
                type="text"
                value={categoryFormData.name}
                onChange={(e) =>
                  setCategoryFormData({
                    ...categoryFormData,
                    name: e.target.value,
                    slug: e.target.value.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, ''),
                  })
                }
                className="admin-input"
                required
              />
            </div>
            <div>
                  })
                }
                className="admin-input"
                required
              />
            </div>
            <div>
              <label className="admin-label">Slug *</label>
              <input
                type="text"
                value={categoryFormData.slug}
                onChange={(e) => setCategoryFormData({ ...categoryFormData, slug: e.target.value })}
                className="admin-input"
                required
              />
            </div>
            <div>
              <label className="admin-label">Description</label>
              <textarea
                value={categoryFormData.description}
                onChange={(e) => setCategoryFormData({ ...categoryFormData, description: e.target.value })}
                className="admin-input"
                rows="3"
              />
            </div>
            <div>
              <label className="admin-label">Image URL</label>
              <input
                type="text"
                value={categoryFormData.image_url}
                onChange={(e) => setCategoryFormData({ ...categoryFormData, image_url: e.target.value })}
                className="admin-input"
              />
            </div>
            <div>
              <label className="admin-label">Order</label>
              <input
                type="number"
                value={categoryFormData.order}
                onChange={(e) => setCategoryFormData({ ...categoryFormData, order: e.target.value })}
                className="admin-input"
              />
            </div>
            <label className="flex items-center space-x-2">
              <input
                type="checkbox"
                checked={categoryFormData.is_active}
                onChange={(e) => setCategoryFormData({ ...categoryFormData, is_active: e.target.checked })}
              />
              <span>Active</span>
            </label>
          </div>
          <div className="mt-6 flex justify-end space-x-3">
            <button type="button" onClick={() => setCategoryModalOpen(false)} className="admin-btn-secondary">
              Cancel
            </button>
            <button type="submit" className="admin-btn-primary">
              {editingCategory ? 'Update' : 'Create'}
            </button>
          </div>
        </form>
      </AdminModal>
    </div>
  );
};

export default AdminCourses;
